Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Representation
  <div style="display:flex;gap:3px;flex-wrap:wrap;">
    <button id="btnPanelA" class="active">Ball &amp; stick (a)</button>
