</label>
<label style="margin-top:4px;font-size:10px;color:#555;">Click C1 or C5 to highlight in Newman view</label>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec ──────────────────────────────────────────────────────────
   PANEL A: 6 C spheres SphereGeometry(0.22) #4a4a4a
            6 C-C bonds CylinderGeometry(0.05) #aebfd0
            12 H spheres SphereGeometry(0.13) #d8d8c8
            12 C-H rods CylinderGeometry(0.03) #aebfd0
   PANEL B: 3 near bonds BoxGeometry bold black; 3 far bonds Line thin black
            6 C-number labels magenta; 12 H labels colored
            2 eye icons (line arcs); 2 dashed sightlines magenta
            "Observer" label
   PANEL C: 2 circle outlines LineLoop black r=0.5
            2 center dots CircleGeometry(0.06) black
            6 bond lines (3/circle) black
            2 bridge lines black; CH2 labels; number labels; H labels
────────────────────────────────────────────────────────────────────────── */

const MAGENTA = '#cc0088';
const GREEN = '#1a8a3c';
const BLUE = '#1a66cc';
const BLACK = '#000000';

// Chair carbon positions
const C_POS = [
  new THREE.Vector3(1.25, 0, 0.25),    // C1
  new THREE.Vector3(0.62, 1.08, -0.25), // C2
  new THREE.Vector3(-0.62, 1.08, 0.25), // C3
  new THREE.Vector3(-1.25, 0, -0.25),   // C4
  new THREE.Vector3(-0.62, -1.08, 0.25),// C5
  new THREE.Vector3(0.62, -1.08, -0.25) // C6
];

// Compute H positions
function getAxialH(ci) {
  const c = C_POS[ci];
  const sign = c.z >= 0 ? 1 : -1;
  return new THREE.Vector3(c.x, c.y, c.z + sign * 0.9);
}
function getEquatorialH(ci) {
  const c = C_POS[ci];
  const sign = c.z >= 0 ? 1 : -1;
  const radial = new THREE.Vector3(c.x, c.y, 0).normalize();
  return new THREE.Vector3(
    c.x + radial.x * 0.9,
    c.y + radial.y * 0.9,
    c.z - sign * 0.35
  );
}

// Helper: cylinder between two points
function cylBetween(p1, p2, radius, color) {
  const dir = new THREE.Vector3().subVectors(p2, p1);
  const len = dir.length();
  const geom = new THREE.CylinderGeometry(radius, radius, len, 8);
  const mat = new THREE.MeshBasicMaterial({ color });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.copy(p1).add(p2).multiplyScalar(0.5);
  const up = new THREE.Vector3(0, 1, 0);
  mesh.quaternion.setFromUnitVectors(up, dir.clone().normalize());
  return mesh;
}

// Helper: bold line (box) between two 2D points in XY plane
function boldLine2D(p1, p2, thickness, color) {
  const dx = p2.x - p1.x, dy = p2.y - p1.y;
  const len = Math.sqrt(dx * dx + dy * dy);
  const angle = Math.atan2(dy, dx);
  const geom = new THREE.BoxGeometry(len, thickness, 0.01);
  const mat = new THREE.MeshBasicMaterial({ color });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.set((p1.x + p2.x) / 2, (p1.y + p2.y) / 2, 0);
  mesh.rotation.z = angle;
  return mesh;
}

// Helper: thin line between two 2D points
function thinLine2D(p1, p2, color) {
  const geom = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(p1.x, p1.y, 0),
    new THREE.Vector3(p2.x, p2.y, 0)
  ]);
  const mat = new THREE.LineBasicMaterial({ color });
  return new THREE.Line(geom, mat);
}

// ═══════════════════════════════════════════════════════════════════════════
// PANEL A: Ball & Stick
// ═══════════════════════════════════════════════════════════════════════════
const panelA = new THREE.Group();
const carbonMeshes = [];
const hMeshes = []; // [ci][0=axial, 1=equatorial]

// Carbon spheres
for (let i = 0; i < 6; i++) {
  const geom = new THREE.SphereGeometry(0.22, 16, 16);
  const mat = new THREE.MeshBasicMaterial({ color: 0x4a4a4a });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.copy(C_POS[i]);
  mesh.userData.carbonIndex = i + 1;
  panelA.add(mesh);
  carbonMeshes.push(mesh);
  registerInteractive(mesh, {
    title: `Carbon ${i + 1}`,
    body: `C${i + 1} in the chair conformation. Click to highlight in Newman projection.`,
    tooltip: `C${i + 1} – click to highlight`
  });
}

// C-C bonds
for (let i = 0; i < 6; i++) {
  const j = (i + 1) % 6;
  panelA.add(cylBetween(C_POS[i], C_POS[j], 0.05, 0xaebfd0));
}

// H spheres and rods
for (let i = 0; i < 6; i++) {
  const axH = getAxialH(i);
  const eqH = getEquatorialH(i);
  hMeshes[i] = [];

  // Axial H
  const axGeom = new THREE.SphereGeometry(0.13, 12, 12);
  const axMat = new THREE.MeshBasicMaterial({ color: 0xd8d8c8 });
  const axMesh = new THREE.Mesh(axGeom, axMat);
  axMesh.position.copy(axH);
  panelA.add(axMesh);
  panelA.add(cylBetween(C_POS[i], axH, 0.03, 0xaebfd0));
  hMeshes[i][0] = axMesh;

  // Equatorial H
  const eqGeom = new THREE.SphereGeometry(0.13, 12, 12);
  const eqMat = new THREE.MeshBasicMaterial({ color: 0xd8d8c8 });
  const eqMesh = new THREE.Mesh(eqGeom, eqMat);
  eqMesh.position.copy(eqH);
  panelA.add(eqMesh);
  panelA.add(cylBetween(C_POS[i], eqH, 0.03, 0xaebfd0));
  hMeshes[i][1] = eqMesh;
}
scene.add(panelA);

// ═══════════════════════════════════════════════════════════════════════════
// PANEL B: Line Structure
// ═══════════════════════════════════════════════════════════════════════════
const panelB = new THREE.Group();
const panelBLabels = [];

// 2D positions for line structure
const B_POS = [
  { x: 1.2, y: -0.5 },   // C1
  { x: 0.3, y: -0.9 },   // C2
  { x: -0.8, y: -0.6 },  // C3
  { x: -1.3, y: 0.4 },   // C4
  { x: -0.2, y: 0.7 },   // C5
  { x: 1.0, y: 0.4 }     // C6
];

// Near bonds (bold): C1-C2, C2-C3, C3-C4
const nearBonds = [[0, 1], [1, 2], [2, 3]];
for (const [i, j] of nearBonds) {
  panelB.add(boldLine2D(B_POS[i], B_POS[j], 0.06, 0x000000));
}

// Far bonds (thin): C4-C5, C5-C6, C6-C1
const farBonds = [[3, 4], [4, 5], [5, 0]];
for (const [i, j] of farBonds) {
  panelB.add(thinLine2D(B_POS[i], B_POS[j], 0x000000));
}

// Carbon number labels
const bNumOffsets = [[0.15, -0.2], [0.1, -0.2], [-0.15, -0.2], [-0.15, 0.2], [-0.1, 0.2], [0.15, 0.2]];
for (let i = 0; i < 6; i++) {
  const lbl = addLabel(`${i + 1}`, new THREE.Vector3(B_POS[i].x + bNumOffsets[i][0], B_POS[i].y + bNumOffsets[i][1], 0), { color: MAGENTA, fontSize: '14px', bold: true });
  panelBLabels.push(lbl);
}

// H positions and colors for panel B
// [carbon][0=axial, 1=equatorial] → {dx, dy, color}
const bHData = [
  [{ dx: 0.1, dy: 0.35, color: BLUE }, { dx: 0.4, dy: -0.15, color: BLACK }],     // C1
  [{ dx: 0, dy: -0.35, color: GREEN }, { dx: -0.35, dy: -0.15, color: BLACK }],   // C2
  [{ dx: -0.1, dy: 0.35, color: BLACK }, { dx: -0.4, dy: -0.1, color: GREEN }],   // C3
  [{ dx: -0.1, dy: -0.35, color: MAGENTA }, { dx: -0.4, dy: 0.15, color: GREEN }],// C4
  [{ dx: 0, dy: 0.35, color: GREEN }, { dx: 0.35, dy: 0.15, color: BLACK }],      // C5
  [{ dx: 0.1, dy: -0.35, color: BLACK }, { dx: 0.4, dy: 0.15, color: GREEN }]     // C6
];

const bHLabels = [];
for (let i = 0; i < 6; i++) {
  for (let h = 0; h < 2; h++) {
    const hd = bHData[i][h];
    const hx = B_POS[i].x + hd.dx;
    const hy = B_POS[i].y + hd.dy;
    // Draw bond line from carbon to H position
    panelB.add(thinLine2D(B_POS[i], { x: hx, y: hy }, 0x000000));
    // H label
    const lbl = addLabel('H', new THREE.Vector3(hx + (hd.dx > 0 ? 0.12 : hd.dx < 0 ? -0.12 : 0), hy + (hd.dy > 0 ? 0.12 : hd.dy < 0 ? -0.12 : 0), 0), { color: hd.color, fontSize: '12px', bold: true });
    panelBLabels.push(lbl);
    bHLabels.push(lbl);
  }
}

// Eye icons (two stylized eyes to the right)
function createEye(cx, cy) {
  const group = new THREE.Group();
  const pts = [];
  const n = 20;
  // Upper lid
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const x = cx - 0.25 + t * 0.5;
    const y = cy + 0.12 * Math.sin(Math.PI * t);
    pts.push(new THREE.Vector3(x, y, 0));
  }
  const upperGeom = new THREE.BufferGeometry().setFromPoints(pts);
  group.add(new THREE.Line(upperGeom, new THREE.LineBasicMaterial({ color: 0x333333 })));
  // Lower lid
  const pts2 = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const x = cx - 0.25 + t * 0.5;
    const y = cy - 0.12 * Math.sin(Math.PI * t);
    pts2.push(new THREE.Vector3(x, y, 0));
  }
  const lowerGeom = new THREE.BufferGeometry().setFromPoints(pts2);
  group.add(new THREE.Line(lowerGeom, new THREE.LineBasicMaterial({ color: 0x333333 })));
  // Iris
  const irisGeom = new THREE.CircleGeometry(0.06, 16);
  const irisMat = new THREE.MeshBasicMaterial({ color: 0x333333 });
  const iris = new THREE.Mesh(irisGeom, irisMat);
  iris.position.set(cx, cy, 0.001);
  group.add(iris);
  return group;
}

const eye1Pos = { x: 2.5, y: 0.3 };
const eye2Pos = { x: 2.8, y: -0.5 };
panelB.add(createEye(eye1Pos.x, eye1Pos.y));
panelB.add(createEye(eye2Pos.x, eye2Pos.y));

// Observer label
const obsLbl = addLabel('Observer', new THREE.Vector3(2.65, -1.0, 0), { color: BLACK, fontSize: '12px' });
panelBLabels.push(obsLbl);

// Dashed sightlines from eyes to C1 and C5
function dashedLine(p1, p2, color) {
  const geom = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(p1.x, p1.y, 0),
    new THREE.Vector3(p2.x, p2.y, 0)
  ]);
  const mat = new THREE.LineDashedMaterial({ color, dashSize: 0.12, gapSize: 0.06 });
  const line = new THREE.Line(geom, mat);
  line.computeLineDistances();
  return line;
}

panelB.add(dashedLine(eye1Pos, B_POS[0], 0xcc0088)); // eye1 → C1
panelB.add(dashedLine(eye2Pos, B_POS[4], 0xcc0088)); // eye2 → C5

// Invisible click targets for C1 and C5 in panel B
const clickTargetsB = [];
for (const ci of [0, 4]) { // C1 and C5
  const geom = new THREE.SphereGeometry(0.25, 8, 8);
  const mat = new THREE.MeshBasicMaterial({ visible: false });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.set(B_POS[ci].x, B_POS[ci].y, 0);
  mesh.userData.carbonIndex = ci + 1;
  panelB.add(mesh);
  clickTargetsB.push(mesh);
  registerInteractive(mesh, {
    title: `Carbon ${ci + 1}`,
    body: `Click to highlight C${ci + 1} in the Newman projection.`,
    tooltip: `C${ci + 1} – click to highlight`
  });
}

scene.add(panelB);

// ═══════════════════════════════════════════════════════════════════════════
// PANEL C: Newman Projection
// ═══════════════════════════════════════════════════════════════════════════
const panelC = new THREE.Group();
const panelCLabels = [];

const LC = { x: -1.0, y: 0 }; // left circle center (C1)
const RC = { x: 1.0, y: 0 };  // right circle center (C5)
const CR = 0.5; // circle radius

// Circle outlines
function circleOutline(cx, cy, r) {
  const pts = [];
  const n = 48;
  for (let i = 0; i <= n; i++) {
    const a = (i / n) * Math.PI * 2;
    pts.push(new THREE.Vector3(cx + r * Math.cos(a), cy + r * Math.sin(a), 0));
  }
  const geom = new THREE.BufferGeometry().setFromPoints(pts);
  return new THREE.Line(geom, new THREE.LineBasicMaterial({ color: 0x000000 }));
}
panelC.add(circleOutline(LC.x, LC.y, CR));
panelC.add(circleOutline(RC.x, RC.y, CR));

// Center dots
function centerDot(cx, cy) {
  const geom = new THREE.CircleGeometry(0.06, 16);
  const mat = new THREE.MeshBasicMaterial({ color: 0x000000 });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.set(cx, cy, 0.001);
  return mesh;
}
const dotL = centerDot(LC.x, LC.y);
