let currentPanel = 'a';
let selectedCarbon = null; // null, 1, or 5

function setPanel(name) {
  currentPanel = name;
  panelA.visible = name === 'a';
  panelB.visible = name === 'b';
  panelC.visible = name === 'c';

  // Label visibility
  for (const lbl of panelBLabels) lbl.div.style.display = name === 'b' ? '' : 'none';
  for (const lbl of panelCLabels) lbl.div.style.display = name === 'c' ? '' : 'none';

  // Orbit control
  controls.enableRotate = name === 'a';

  // Camera
  if (name === 'a') {
    setCameraView({ projection: 'perspective', azimuthDeg: 35, elevationDeg: 18, heightFraction: 0.62 });
  } else {
    setCameraView({ projection: 'perspective', azimuthDeg: 90, elevationDeg: 0, heightFraction: 0.62 });
  }

  // Button states
  document.getElementById('btnPanelA').classList.toggle('active', name === 'a');
  document.getElementById('btnPanelB').classList.toggle('active', name === 'b');
  document.getElementById('btnPanelC').classList.toggle('active', name === 'c');
}

document.getElementById('btnPanelA').addEventListener('click', () => setPanel('a'));
document.getElementById('btnPanelB').addEventListener('click', () => setPanel('b'));
document.getElementById('btnPanelC').addEventListener('click', () => setPanel('c'));

