// Eye icons
function createEye(cx, cy) {
  const group = new THREE.Group();
  const pts = [];
  const n = 20;
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const x = cx - 0.22 + t * 0.44;
    const y = cy + 0.11 * Math.sin(Math.PI * t);
    pts.push(new THREE.Vector3(x, y, 0));
  }
  group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color: 0x333333 })));
  const pts2 = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const x = cx - 0.22 + t * 0.44;
    const y = cy - 0.11 * Math.sin(Math.PI * t);
    pts2.push(new THREE.Vector3(x, y, 0));
  }
  group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts2), new THREE.LineBasicMaterial({ color: 0x333333 })));
  const irisGeom = new THREE.CircleGeometry(0.05, 16);
  const iris = new THREE.Mesh(irisGeom, new THREE.MeshBasicMaterial({ color: 0x333333 }));
  iris.position.set(cx, cy, 0.001);
  group.add(iris);
  return group;
}

