// HIGHLIGHT / SELECTION
// ═══════════════════════════════════════════════════════════════════════════
function highlightCarbon(ci) {
  selectedCarbon = ci;
  for (let i = 0; i < 6; i++) {
    carbonMeshes[i].material.color.set(0x4a4a4a);
    hMeshes[i][0].material.color.set(0xd8d8c8);
    hMeshes[i][1].material.color.set(0xd8d8c8);
  }
  dotL.material.color.set(0x000000);
  dotR.material.color.set(0x000000);

  if (ci === 1) {
    carbonMeshes[0].material.color.set(0xffcc00);
    hMeshes[0][0].material.color.set(0xffcc00);
    hMeshes[0][1].material.color.set(0xffcc00);
    dotL.material.color.set(0xffcc00);
  } else if (ci === 5) {
    carbonMeshes[4].material.color.set(0xffcc00);
    hMeshes[4][0].material.color.set(0xffcc00);
    hMeshes[4][1].material.color.set(0xffcc00);
    dotR.material.color.set(0xffcc00);
  }
}

canvas.addEventListener('click', (event) => {
  const rect = canvas.getBoundingClientRect();
  const pointer = new THREE.Vector2(
    ((event.clientX - rect.left) / rect.width) * 2 - 1,
    -((event.clientY - rect.top) / rect.height) * 2 + 1
  );
  const raycaster = new THREE.Raycaster();
  raycaster.setFromCamera(pointer, camera);

  if (currentPanel === 'a') {
    const hits = raycaster.intersectObjects(carbonMeshes);
    if (hits.length > 0) {
      const ci = hits[0].object.userData.carbonIndex;
      if (ci === 1 || ci === 5) {
        highlightCarbon(selectedCarbon === ci ? null : ci);
        return;
      }
    }
  }
  if (currentPanel === 'b') {
    const hits = raycaster.intersectObjects(clickTargetsB);
    if (hits.length > 0) {
      const ci = hits[0].object.userData.carbonIndex;
      if (ci === 1 || ci === 5) {
        highlightCarbon(selectedCarbon === ci ? null : ci);
        return;
      }
    }
  }
});

